ee:variables.ee:set-variable:
%dw 2.0
output application/json

fun toColumnLetter(idx) =
    if (idx < 26) 
        ("ABCDEFGHIJKLMNOPQRSTUVWXYZ"[idx to idx])
    else
        toColumnLetter((idx / 26) as Number - 1) ++ ("ABCDEFGHIJKLMNOPQRSTUVWXYZ"[(idx mod 26) to (idx mod 26)])

fun getColumnRange(startIdx, endIdx) = 
    (startIdx to endIdx) map toColumnLetter($)

// MTD column Indexes
var previousMonthEndIndex = (vars."mtdPreviousMonthIndex" as Number)
var currentMonthStartIndex = previousMonthEndIndex + 1
var currentMonthEndIndex = previousMonthEndIndex + 8

// Inventory Column Indexes
var previousMonthLastDateIndex = vars."previousMonthLastDateIndex"
var currentMonthStartDateIndex = vars."currentMonthStartDateIndex"


//var currentMonthPreviousDateIndex= vars."current-month-previous-date-index" //
//var currentDateIndex = vars. // 

// MTD -- Calculate column names for the specific indices
var previousMonthEndColumn = toColumnLetter(previousMonthEndIndex)
var currentMonthStartColumn = toColumnLetter(currentMonthStartIndex)
var currentMonthEndColumn = toColumnLetter(currentMonthEndIndex)

// Inventory -- Calculate column names for the specific indices
var previousMonthLastDateColumn = toColumnLetter(previousMonthLastDateIndex)
var currentMonthStartDateColumn = toColumnLetter(currentMonthStartDateIndex)
var currentMonthPreviousDateColumn = vars.numberToColumn.CurrentColumn  //toColumnLetter(currentMonthPreviousDateIndex)
var currentDateColumn = vars.numberToColumn.NextColumn  //toColumnLetter(currentMonthStartDateIndex)

---
{
	// MTD column-names
   monthEndRangeColumns: getColumnRange(currentMonthStartIndex, currentMonthEndIndex),
   mtdPreviousMonthEndColumn: previousMonthEndColumn,
   currentMonthStartColumn: currentMonthStartColumn,

   // Inventory column-names
   previousMonthLastDateColumn: previousMonthLastDateColumn,
   currentMonthStartDateColumn: currentMonthStartDateColumn,
   currentMonthPreviousDateColumn: currentMonthPreviousDateColumn,
   currentDateColumn: currentDateColumn,
}

%dw 2.0
output application/json
var headers = vars."newMtdHeaders"
---
{
	values: vars."mtdSampleFormulas" map ((row, index) ->
    if (index == 0) headers
    else row
)
}
